CREATE FUNCTION public.guard_dcm_tranche_values() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t jsonb; previous jsonb; k text; allowed text[]:=ARRAY['IssuanceDataGroup/Issuance/SpecifiedCurrency','IssuanceDataGroup/Issuance/TotalAggregateAmount/Value','IssuanceDataGroup/Product/AggregateNominalAmount/Value','IssuanceDataGroup/Product/Maturity/MaturityDate','IssuanceDataGroup/Product/InterestPayment/InterestType']; BEGIN IF auth.uid() IS NULL OR public.is_admin(auth.uid()) OR NOT public.has_role(auth.uid(),'dcm') THEN RETURN NEW; END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(coalesce(NEW.deal_workspace->'tranches','[]')) LOOP
 SELECT value INTO previous FROM jsonb_array_elements(coalesce(OLD.deal_workspace->'tranches','[]')) WHERE value->>'id'=t->>'id';
 IF previous IS NOT NULL AND (previous-'label'-'currency'-'amount'-'tenor'-'rateType'-'values') IS DISTINCT FROM (t-'label'-'currency'-'amount'-'tenor'-'rateType'-'values') THEN RAISE EXCEPTION 'DCM cannot change tranche legal status'; END IF;
 IF previous IS NULL AND coalesce(t->>'seniority','senior_unsecured')<>'senior_unsecured' THEN RAISE EXCEPTION 'DCM cannot set tranche legal status'; END IF;
 FOR k IN SELECT jsonb_object_keys(coalesce(t->'values','{}')||coalesce(previous->'values','{}')) LOOP IF NOT k=ANY(allowed) AND t->'values'->k IS DISTINCT FROM previous->'values'->k THEN RAISE EXCEPTION 'DCM can edit structure fields only: %',k; END IF; END LOOP;
 END LOOP; RETURN NEW; END $$;
CREATE TRIGGER guard_dcm_tranche_values BEFORE UPDATE ON public.deals FOR EACH ROW EXECUTE FUNCTION public.guard_dcm_tranche_values();
CREATE FUNCTION public.guard_execution_transition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND public.deal_phase(OLD.id)='setup' AND (NEW.stage NOT IN ('Mandate','Announced') OR coalesce((NEW.bdt_state->>'stage')::int,1)>=2 OR coalesce(NEW.bdt_state->'f'->>'x:iptSpread','')<>'') THEN RAISE EXCEPTION 'Use Move to execution after resolving blocking checks and completing actor sign-offs'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_execution_transition BEFORE UPDATE ON public.deals FOR EACH ROW EXECUTE FUNCTION public.guard_execution_transition();
CREATE POLICY actor_create_releases ON public.deal_term_sheet_releases FOR INSERT TO authenticated WITH CHECK(public.copilot_editor(deal_id) AND released_by=auth.uid()::text);
CREATE FUNCTION public.deal_team_directory(_deal text) RETURNS TABLE(user_id uuid,role public.app_role,name text,organization text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT t.user_id,t.role,p.name,p.organization FROM public.deal_team_members t JOIN public.profiles p ON p.user_id=t.user_id WHERE t.deal_id=_deal AND public.copilot_member(_deal) $$;
REVOKE ALL ON FUNCTION public.deal_team_directory(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.deal_team_directory(text) TO authenticated,service_role;
CREATE FUNCTION public.admin_set_actor_role(_legacy text,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF NOT public.is_admin(auth.uid()) OR _role::text NOT IN ('dcm','issuer_legal','counsel') THEN RAISE EXCEPTION 'Administrator required for actor roles'; END IF; SELECT p.user_id INTO uid FROM public.profiles p JOIN public.users u ON lower(u.email)=lower(p.email) WHERE u.id=_legacy AND p.status='approved'; IF uid IS NULL THEN RETURN; END IF; IF public.has_role(uid,'master_admin') THEN RAISE EXCEPTION 'Master admin role cannot be changed here'; END IF; DELETE FROM public.user_roles WHERE user_id=uid; INSERT INTO public.user_roles(user_id,role) VALUES(uid,_role); INSERT INTO public.audit_log(id,action,entity_type,entity_id,user_id,details) VALUES(gen_random_uuid()::text,'ACTOR_ROLE_CHANGED','user',uid::text,auth.uid()::text,_role::text); END $$;
REVOKE ALL ON FUNCTION public.admin_set_actor_role(text,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_set_actor_role(text,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.guard_signoff_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.deal_id,NEW.item_key,NEW.role) IS DISTINCT FROM (OLD.deal_id,OLD.item_key,OLD.role) THEN RAISE EXCEPTION 'Sign-off identity cannot change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_signoff_identity BEFORE UPDATE ON public.deal_signoffs FOR EACH ROW EXECUTE FUNCTION public.guard_signoff_identity();